const workcenterId = $state.context.boundary.workcenterId;
const timezone = $state.context.boundary.timezone;
const workcenter = $state.context.boundary.workcenter;
const currentSchedule = $state.context.boundary.currentSchedule;
const boundaries = $state.context.boundary.boundaries;

const n = (v) => v || 0;
const clamp = (v) => Math.max(0, Math.min(1, v));
const pct = (v) => v != null ? (v * 100).toFixed(2) + "%" : "N/A";

const formatDuration = (ms) => {
  if (ms == null || ms === 0) return "0m";
  const hours = Math.floor(ms / 3600000);
  const mins = Math.floor((ms % 3600000) / 60000);
  return hours > 0 ? `${hours}h ${mins}m` : `${mins}m`;
};

const formatPctChange = (change) => {
  if (change == null) return "N/A";
  const sign = change >= 0 ? "+" : "";
  return sign + (change * 100).toFixed(1) + "%";
};

const getDurationMs = (values) => {
  if (!values || values.length === 0) return 0;
  
  let totalMs = 0;
  values.forEach(v => {
    if (typeof v === 'object' && v !== null && v.milliseconds !== undefined) {
      totalMs += n(v.milliseconds);
    }
  });
  return totalMs;
};

const sumHourlyAggregates = (nodes) => {
  return nodes.reduce((acc, node) => {
    const agg = node._aggregate || {};
    return {
      goodUnits: acc.goodUnits + n(agg.goodUnits?.sum),
      scrapUnits: acc.scrapUnits + n(agg.scrapUnits?.sum),
      totalUnits: acc.totalUnits + n(agg.totalUnits?.sum),
      idealUnits: acc.idealUnits + n(agg.idealUnits?.sum),
      runMinutesMs: acc.runMinutesMs + getDurationMs(agg.runMinutes?.values),
      downtimeMinutesMs: acc.downtimeMinutesMs + getDurationMs(agg.downtimeMinutes?.values),
      plannedDowntimeMinutesMs: acc.plannedDowntimeMinutesMs + getDurationMs(agg.plannedDowntimeMinutes?.values),
      scheduledTimeMs: acc.scheduledTimeMs + getDurationMs(agg.scheduledTime?.values)
    };
  }, {
    goodUnits: 0,
    scrapUnits: 0,
    totalUnits: 0,
    idealUnits: 0,
    runMinutesMs: 0,
    downtimeMinutesMs: 0,
    plannedDowntimeMinutesMs: 0,
    scheduledTimeMs: 0
  });
};

const calculateOEE = (totals) => {
  const scheduledMs = totals.scheduledTimeMs;
  const runMs = totals.runMinutesMs;
  const goodUnits = totals.goodUnits;
  const totalUnits = totals.totalUnits;
  const idealUnits = totals.idealUnits;
  
  if (scheduledMs === 0) {
    return {
      availability: null,
      performance: null,
      quality: null,
      oee: null,
      isScheduled: false
    };
  }
  
  const availability = clamp(runMs / scheduledMs);
  const performance = idealUnits > 0 ? clamp(totalUnits / idealUnits) : 1;
  const quality = totalUnits > 0 ? clamp(goodUnits / totalUnits) : 1;
  const oee = availability * performance * quality;
  
  return {
    availability,
    performance,
    quality,
    oee,
    availabilityPct: pct(availability),
    performancePct: pct(performance),
    qualityPct: pct(quality),
    oeePct: pct(oee),
    isScheduled: true
  };
};

const sumOperatingTime = (nodes) => {
  return nodes.reduce((sum, node) => {
    return sum + n(node._aggregate?.runTime?.sum);
  }, 0);
};

const sumFaults = (nodes) => {
  let faultCount = 0;
  let repairTimeMs = 0;
  
  nodes.forEach(node => {
    faultCount += n(node._aggregate?.id?.count);
    repairTimeMs += n(node._aggregate?.runTime?.sum);
  });
  
  return { faultCount, repairTimeMs };
};

const calculateReliabilityPeriod = (operatingTimeMs, faultCount, repairTimeMs) => {
  const mtbf = faultCount > 0 ? operatingTimeMs / faultCount : null;
  const mttr = faultCount > 0 ? repairTimeMs / faultCount : null;
  
  return {
    mtbf,
    mtbfFormatted: mtbf != null ? formatDuration(mtbf) : "N/A",
    mttr,
    mttrFormatted: mttr != null ? formatDuration(mttr) : "N/A",
    faultCount,
    operatingTimeMs,
    operatingTime: formatDuration(operatingTimeMs),
    repairTimeMs,
    repairTime: formatDuration(repairTimeMs)
  };
};

const oeeHourly24h = $.oeeHourly24h?.edges?.map(e => e.node) || [];
const oeeHourlyDay = $.oeeHourlyDay?.edges?.map(e => e.node) || [];
const oeeHourlyShift = $.oeeHourlyShift?.edges?.map(e => e.node) || [];
const oeeHourly90d = $.oeeHourly90d?.edges?.map(e => e.node) || [];
const currentHourHistory = $.currentHourHistory?.edges?.map(e => e.node) || [];
const currentHourProduction = $.currentHourProduction?.edges?.map(e => e.node) || [];
const downtimeByEvent24h = $.downtimeByEvent24h?.edges?.map(e => e.node) || [];
const downtimeByEventShift = $.downtimeByEventShift?.edges?.map(e => e.node) || [];

const operatingTime0to30dNodes = $.operatingTime0to30d?.edges?.map(e => e.node) || [];
const operatingTime30to60dNodes = $.operatingTime30to60d?.edges?.map(e => e.node) || [];
const operatingTime60to90dNodes = $.operatingTime60to90d?.edges?.map(e => e.node) || [];
const faults0to30dNodes = $.faults0to30d?.edges?.map(e => e.node) || [];
const faults30to60dNodes = $.faults30to60d?.edges?.map(e => e.node) || [];
const faults60to90dNodes = $.faults60to90d?.edges?.map(e => e.node) || [];

const totals24h = sumHourlyAggregates(oeeHourly24h);
const oee24h = calculateOEE(totals24h);

const metrics24h = {
  ...oee24h,
  ...totals24h,
  runTime: formatDuration(totals24h.runMinutesMs),
  downtime: formatDuration(totals24h.downtimeMinutesMs),
  scheduledTime: formatDuration(totals24h.scheduledTimeMs),
  hourCount: oeeHourly24h.length
};

const totalsDay = sumHourlyAggregates(oeeHourlyDay);
const oeeDay = calculateOEE(totalsDay);

const metricsDay = {
  ...oeeDay,
  ...totalsDay,
  runTime: formatDuration(totalsDay.runMinutesMs),
  downtime: formatDuration(totalsDay.downtimeMinutesMs),
  scheduledTime: formatDuration(totalsDay.scheduledTimeMs),
  hourCount: oeeHourlyDay.length
};

const totalsShift = sumHourlyAggregates(oeeHourlyShift);
const oeeShift = calculateOEE(totalsShift);

const metricsShift = {
  ...oeeShift,
  ...totalsShift,
  runTime: formatDuration(totalsShift.runMinutesMs),
  downtime: formatDuration(totalsShift.downtimeMinutesMs),
  scheduledTime: formatDuration(totalsShift.scheduledTimeMs),
  hourCount: oeeHourlyShift.length,
  shiftStart: boundaries.shiftStart,
  shiftEnd: boundaries.shiftEnd
};

const totals90d = sumHourlyAggregates(oeeHourly90d);
const oee90d = calculateOEE(totals90d);

const metrics90d = {
  ...oee90d,
  ...totals90d,
  runTime: formatDuration(totals90d.runMinutesMs),
  downtime: formatDuration(totals90d.downtimeMinutesMs),
  scheduledTime: formatDuration(totals90d.scheduledTimeMs),
  dayCount: oeeHourly90d.length
};

const currentHourStartMs = $moment(boundaries.currentHourStart).valueOf();
const currentHourEndMs = $moment(boundaries.currentHourEnd).valueOf();
const nowMs = $moment(boundaries.now).valueOf();

let currentHourRunMs = 0;
let currentHourDowntimeMs = 0;
let currentHourPlannedDowntimeMs = 0;

currentHourHistory.forEach(rec => {
  const occMs = $moment(rec.occurAt).valueOf();
  const endMs = rec.endAt ? $moment(rec.endAt).valueOf() : nowMs;
  
  const overlapStart = Math.max(occMs, currentHourStartMs);
  const overlapEnd = Math.min(endMs, currentHourEndMs, nowMs);
  const duration = Math.max(0, overlapEnd - overlapStart);
  
  if (rec.mode?.countAsProductionTime) {
    currentHourRunMs += duration;
  }
  if (rec.mode?.countAsDowntime) {
    currentHourDowntimeMs += duration;
  }
  if (rec.mode?.countAsPlannedDowntime) {
    currentHourPlannedDowntimeMs += duration;
  }
});

const currentHourGoodUnits = currentHourProduction.reduce((sum, p) => sum + n(p.quantityGood), 0);
const currentHourScrapUnits = currentHourProduction.reduce((sum, p) => sum + n(p.quantityScrap), 0);
const currentHourIdealUnits = currentHourProduction.reduce((sum, p) => sum + n(p.idealUnits), 0);
const currentHourTotalUnits = currentHourGoodUnits + currentHourScrapUnits;

const elapsedMs = nowMs - currentHourStartMs;

const currentHourTotals = {
  goodUnits: currentHourGoodUnits,
  scrapUnits: currentHourScrapUnits,
  totalUnits: currentHourTotalUnits,
  idealUnits: currentHourIdealUnits,
  runMinutesMs: currentHourRunMs,
  scheduledTimeMs: elapsedMs
};

const currentHourOEE = calculateOEE(currentHourTotals);

const metricsCurrentHour = {
  ...currentHourOEE,
  ...currentHourTotals,
  isLive: true,
  elapsedMs,
  elapsed: formatDuration(elapsedMs),
  runTime: formatDuration(currentHourRunMs),
  downtime: formatDuration(currentHourDowntimeMs)
};

const calendarTime24h = 24 * 60 * 60 * 1000;
const loading24h = totals24h.scheduledTimeMs / calendarTime24h;
const teep24h = oee24h.oee != null ? oee24h.oee * loading24h : null;

const metricsTeep = {
  teep: teep24h,
  teepPct: pct(teep24h),
  loading: loading24h,
  loadingPct: pct(loading24h),
  calendarTimeMs: calendarTime24h,
  scheduledTimeMs: totals24h.scheduledTimeMs
};

const opTime0to30d = sumOperatingTime(operatingTime0to30dNodes);
const opTime30to60d = sumOperatingTime(operatingTime30to60dNodes);
const opTime60to90d = sumOperatingTime(operatingTime60to90dNodes);

const faults0to30d = sumFaults(faults0to30dNodes);
const faults30to60d = sumFaults(faults30to60dNodes);
const faults60to90d = sumFaults(faults60to90dNodes);

const reliability0to30d = calculateReliabilityPeriod(opTime0to30d, faults0to30d.faultCount, faults0to30d.repairTimeMs);
const reliability30to60d = calculateReliabilityPeriod(opTime30to60d, faults30to60d.faultCount, faults30to60d.repairTimeMs);
const reliability60to90d = calculateReliabilityPeriod(opTime60to90d, faults60to90d.faultCount, faults60to90d.repairTimeMs);

const opTime90d = opTime0to30d + opTime30to60d + opTime60to90d;
const faults90dTotal = {
  faultCount: faults0to30d.faultCount + faults30to60d.faultCount + faults60to90d.faultCount,
  repairTimeMs: faults0to30d.repairTimeMs + faults30to60d.repairTimeMs + faults60to90d.repairTimeMs
};
const reliability90d = calculateReliabilityPeriod(opTime90d, faults90dTotal.faultCount, faults90dTotal.repairTimeMs);

const mtbfChangeVsPrior = (reliability30to60d.mtbf != null && reliability30to60d.mtbf > 0) 
  ? (reliability0to30d.mtbf - reliability30to60d.mtbf) / reliability30to60d.mtbf 
  : null;

const mttrChangeVsPrior = (reliability30to60d.mttr != null && reliability30to60d.mttr > 0) 
  ? (reliability0to30d.mttr - reliability30to60d.mttr) / reliability30to60d.mttr 
  : null;

const getMtbfTrend = (change) => {
  if (change == null) return "unknown";
  if (change > 0.1) return "improving";
  if (change < -0.1) return "degrading";
  return "stable";
};

const getMttrTrend = (change) => {
  if (change == null) return "unknown";
  if (change < -0.1) return "improving";
  if (change > 0.1) return "degrading";
  return "stable";
};

const metricsReliability = {
  current: {
    ...reliability0to30d,
    periodLabel: "Last 30 days",
    periodDays: 30
  },
  prior: {
    ...reliability30to60d,
    periodLabel: "30-60 days ago",
    periodDays: 30
  },
  baseline: {
    ...reliability60to90d,
    periodLabel: "60-90 days ago",
    periodDays: 30
  },
  overall: {
    ...reliability90d,
    periodLabel: "Last 90 days",
    periodDays: 90
  },
  trend: {
    mtbfChangeVsPrior,
    mtbfChangeFormatted: formatPctChange(mtbfChangeVsPrior),
    mtbfTrend: getMtbfTrend(mtbfChangeVsPrior),
    mttrChangeVsPrior,
    mttrChangeFormatted: formatPctChange(mttrChangeVsPrior),
    mttrTrend: getMttrTrend(mttrChangeVsPrior)
  },
  summary: {
    mtbf: reliability0to30d.mtbf,
    mtbfFormatted: reliability0to30d.mtbfFormatted,
    mtbfTrendIcon: getMtbfTrend(mtbfChangeVsPrior) === "improving" ? "▲" : getMtbfTrend(mtbfChangeVsPrior) === "degrading" ? "▼" : "→",
    mtbfTrendLabel: formatPctChange(mtbfChangeVsPrior) + " vs prior 30d",
    mttr: reliability0to30d.mttr,
    mttrFormatted: reliability0to30d.mttrFormatted,
    mttrTrendIcon: getMttrTrend(mttrChangeVsPrior) === "improving" ? "▼" : getMttrTrend(mttrChangeVsPrior) === "degrading" ? "▲" : "→",
    mttrTrendLabel: formatPctChange(mttrChangeVsPrior) + " vs prior 30d"
  }
};

const calendarTime90d = 90 * 24 * 60 * 60 * 1000;
const utilization90d = calendarTime90d > 0 ? totals90d.runMinutesMs / calendarTime90d : null;
const operatingHours90d = totals90d.runMinutesMs / 3600000;
const throughput90d = operatingHours90d > 0 ? totals90d.totalUnits / operatingHours90d : null;
const worldClassOEE = 0.85;
const oeeGap90d = oee90d.oee != null ? worldClassOEE - oee90d.oee : null;

const metricsEfficiency = {
  utilization: utilization90d,
  utilizationPct: pct(utilization90d),
  throughput: throughput90d != null ? throughput90d.toFixed(2) + " units/hr" : "N/A",
  throughputRaw: throughput90d,
  oeeGap: oeeGap90d,
  oeeGapPct: oeeGap90d != null ? (oeeGap90d * 100).toFixed(2) + "%" : "N/A",
  worldClassOEE: pct(worldClassOEE),
  windowDays: 90,
  totals: {
    runTimeMs: totals90d.runMinutesMs,
    runTime: formatDuration(totals90d.runMinutesMs),
    totalUnits: totals90d.totalUnits,
    goodUnits: totals90d.goodUnits,
    scrapUnits: totals90d.scrapUnits
  }
};

const downtimeMap24h = {};
downtimeByEvent24h.forEach(node => {
  const eventId = node.eventId;
  if (!downtimeMap24h[eventId]) {
    downtimeMap24h[eventId] = {
      eventId,
      eventCode: node.event?.code,
      totalMs: 0,
      occurrences: 0
    };
  }
  downtimeMap24h[eventId].totalMs += n(node._aggregate?.unplannedDowntime?.sum) + n(node._aggregate?.plannedDowntime?.sum);
  downtimeMap24h[eventId].occurrences += n(node._aggregate?.id?.count);
});

const topDowntimes24h = Object.values(downtimeMap24h)
  .sort((a, b) => b.totalMs - a.totalMs)
  .slice(0, 5)
  .map(d => ({
    ...d,
    totalFormatted: formatDuration(d.totalMs)
  }));

const downtimeMapShift = {};
downtimeByEventShift.forEach(node => {
  const eventId = node.eventId;
  if (!downtimeMapShift[eventId]) {
    downtimeMapShift[eventId] = {
      eventId,
      eventCode: node.event?.code,
      totalMs: 0,
      occurrences: 0
    };
  }
  downtimeMapShift[eventId].totalMs += n(node._aggregate?.unplannedDowntime?.sum) + n(node._aggregate?.plannedDowntime?.sum);
  downtimeMapShift[eventId].occurrences += n(node._aggregate?.id?.count);
});

const topDowntimesShift = Object.values(downtimeMapShift)
  .sort((a, b) => b.totalMs - a.totalMs)
  .slice(0, 5)
  .map(d => ({
    ...d,
    totalFormatted: formatDuration(d.totalMs)
  }));

const idealCycleTimeMs = totalsShift.idealUnits > 0 
  ? totalsShift.scheduledTimeMs / totalsShift.idealUnits 
  : 0;

const qualityLossUnits = totalsShift.scrapUnits;
const performanceLossUnits = Math.max(0, totalsShift.idealUnits - totalsShift.totalUnits);

const lossAnalysis = {
  plannedDowntimeMs: totalsShift.plannedDowntimeMinutesMs,
  unplannedDowntimeMs: totalsShift.downtimeMinutesMs - totalsShift.plannedDowntimeMinutesMs,
  plannedDowntime: formatDuration(totalsShift.plannedDowntimeMinutesMs),
  unplannedDowntime: formatDuration(totalsShift.downtimeMinutesMs - totalsShift.plannedDowntimeMinutesMs),
  performanceLossUnits,
  performanceLossMs: performanceLossUnits * idealCycleTimeMs,
  performanceLoss: formatDuration(performanceLossUnits * idealCycleTimeMs),
  qualityLossUnits,
  qualityLossMs: qualityLossUnits * idealCycleTimeMs,
  qualityLoss: formatDuration(qualityLossUnits * idealCycleTimeMs),
  idealCycleTimeMs
};

const lastHistory = currentHourHistory[currentHourHistory.length - 1];
const currentStatus = lastHistory ? {
  historyId: lastHistory.id,
  startAt: lastHistory.occurAt,
  durationMs: nowMs - $moment(lastHistory.occurAt).valueOf(),
  duration: formatDuration(nowMs - $moment(lastHistory.occurAt).valueOf()),
  mode: lastHistory.mode,
  state: lastHistory.state,
  event: lastHistory.event
} : null;

return {
  workcenterId,
  workcenter,
  timezone,
  currentSchedule,
  lastRefresh: boundaries.now,
  
  currentStatus,
  
  metrics: {
    currentHour: metricsCurrentHour,
    shift: metricsShift,
    day: metricsDay,
    rolling24h: metrics24h,
    rolling90d: metrics90d
  },
  
  teep: metricsTeep,
  reliability: metricsReliability,
  efficiency: metricsEfficiency,
  lossAnalysis,
  
  topDowntimes: {
    shift: topDowntimesShift,
    rolling24h: topDowntimes24h
  }
};

