query OEEDashboardData(
  $wcId: String!
  $window24hStart: DateTime!
  $window30dStart: DateTime!
  $window60dStart: DateTime!
  $window90dStart: DateTime!
  $now: DateTime!
  $currentHourStart: DateTime!
  $currentHourEnd: DateTime!
  $dayStart: DateTime!
  $dayEnd: DateTime!
  $shiftStart: DateTime
  $shiftEnd: DateTime
) {
  
  # OEE HOURLY: 24h Window (grouped by hour)
  oeeHourly24h: oeeHourly(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { periodStartAt: { _gte: $window24hStart } }
        { periodStartAt: { _lt: $now } }
      ]
    }
    orderBy: [{ field: periodStartAt, direction: asc }]
  ) {
    edges {
      node {
        periodStartAt(round: { unit: hour })
        scheduleId
        shift
        oee
        availability
        performance
        quality
        _aggregate {
          goodUnits { sum }
          scrapUnits { sum }
          totalUnits { sum }
          idealUnits { sum }
          runMinutes { values }
          downtimeMinutes { values }
          plannedDowntimeMinutes { values }
          scheduledTime { values }
        }
      }
    }
  }
  
  # OEE HOURLY: Day Window
  oeeHourlyDay: oeeHourly(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { periodStartAt: { _gte: $dayStart } }
        { periodStartAt: { _lt: $dayEnd } }
      ]
    }
    orderBy: [{ field: periodStartAt, direction: asc }]
  ) {
    edges {
      node {
        periodStartAt(round: { unit: hour })
        _aggregate {
          goodUnits { sum }
          scrapUnits { sum }
          totalUnits { sum }
          idealUnits { sum }
          runMinutes { values }
          downtimeMinutes { values }
          plannedDowntimeMinutes { values }
          scheduledTime { values }
        }
      }
    }
  }
  
  # OEE HOURLY: Shift Window
  oeeHourlyShift: oeeHourly(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { periodStartAt: { _gte: $shiftStart } }
        { periodStartAt: { _lt: $shiftEnd } }
      ]
    }
    orderBy: [{ field: periodStartAt, direction: asc }]
  ) {
    edges {
      node {
        periodStartAt(round: { unit: hour })
        _aggregate {
          goodUnits { sum }
          scrapUnits { sum }
          totalUnits { sum }
          idealUnits { sum }
          runMinutes { values }
          downtimeMinutes { values }
          plannedDowntimeMinutes { values }
          scheduledTime { values }
        }
      }
    }
  }
  
  # OEE HOURLY: 90-day Aggregate (for utilization & throughput)
  oeeHourly90d: oeeHourly(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { periodStartAt: { _gte: $window90dStart } }
        { periodStartAt: { _lt: $now } }
      ]
    }
  ) {
    edges {
      node {
        periodStartAt(round: { unit: day })
        _aggregate {
          goodUnits { sum }
          scrapUnits { sum }
          totalUnits { sum }
          idealUnits { sum }
          runMinutes { values }
          downtimeMinutes { values }
          plannedDowntimeMinutes { values }
          scheduledTime { values }
        }
      }
    }
  }
  
  # CURRENT HOUR: WorkcenterHistory (for live calc)
  currentHourHistory: workcenterHistory(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { occurAt: { _lt: $currentHourEnd } }
        { _or: [
          { endAt: { _isNull: true } }
          { endAt: { _gte: $currentHourStart } }
        ]}
      ]
    }
    orderBy: [{ field: occurAt, direction: asc }]
  ) {
    edges {
      node {
        id
        occurAt
        endAt
        runTime
        plannedDowntime
        unplannedDowntime
        mode { 
          id 
          code  
          color
          countAsProductionTime
          countAsDowntime
          countAsPlannedDowntime
        }
        state { id code }
        event { id code }
      }
    }
  }
  
  # CURRENT HOUR: ProductionLog (for live units)
  currentHourProduction: productionLog(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { occurAt: { _gte: $currentHourStart } }
        { occurAt: { _lt: $currentHourEnd } }
      ]
    }
  ) {
    edges {
      node {
        idealUnits
        quantityGood
        quantityScrap
      }
    }
  }
  
  # DOWNTIME BY EVENT: 24h (grouped by eventId for top 5)
  downtimeByEvent24h: workcenterHistory(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { occurAt: { _gte: $window24hStart } }
        { occurAt: { _lt: $now } }
        { mode: { countAsDowntime: { _eq: true } } }
      ]
    }
  ) {
    edges {
      node {
       stateId
        state { id code }
        _aggregate {
          unplannedDowntime { sum }
          plannedDowntime { sum }
          id { count }
        }
      }
    }
  }
  
  # DOWNTIME BY EVENT: Shift (grouped by eventId for top 5)
  downtimeByEventShift: workcenterHistory(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { occurAt: { _gte: $shiftStart } }
        { occurAt: { _lt: $shiftEnd } }
        { mode: { countAsDowntime: { _eq: true } } }
      ]
    }
  ) {
    edges {
      node {
       stateId
        state { id code }
        _aggregate {
          unplannedDowntime { sum }
          plannedDowntime { sum }
          id { count }
        }
      }
    }
  }
    
# ============================================
  # RELIABILITY METRICS: 0-30 DAYS (Current)
  # ============================================
  
  # Operating Time: 0-30 days (excludes fault states)
  operatingTime0to30d: workcenterHistory(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { occurAt: { _gte: $window30dStart } }
        { occurAt: { _lt: $now } }
        { mode: { countAsProductionTime: { _eq: true } } }
        { state: { isFault: { _eq: false } } }
      ]
    }
  ) {
    edges {
      node {
        workcenterId
        _aggregate {
          runTime { sum }
        }
      }
    }
  }
  
  # Faults: 0-30 days (runTime = repair time)
  faults0to30d: workcenterHistory(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { occurAt: { _gte: $window30dStart } }
        { occurAt: { _lt: $now } }
        { state: { isFault: { _eq: true } } }
      ]
    }
  ) {
    edges {
      node {
 
        workcenterId
        _aggregate {
          runTime { sum }
          id { count }
        }
      }
    }
  }
  
  # ============================================
  # RELIABILITY METRICS: 30-60 DAYS (Prior)
  # ============================================
  
  # Operating Time: 30-60 days (excludes fault states)
  operatingTime30to60d: workcenterHistory(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { occurAt: { _gte: $window60dStart } }
        { occurAt: { _lt: $window30dStart } }
        { mode: { countAsProductionTime: { _eq: true } } }
        { state: { isFault: { _eq: false } } }
      ]
    }
  ) {
    edges {
      node {
        workcenterId
        _aggregate {
          runTime { sum }
        }
      }
    }
  }
  
  # Faults: 30-60 days (runTime = repair time)
  faults30to60d: workcenterHistory(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { occurAt: { _gte: $window60dStart } }
        { occurAt: { _lt: $window30dStart } }
        { state: { isFault: { _eq: true } } }
      ]
    }
  ) {
    edges {
      node {

        workcenterId
        _aggregate {
          runTime { sum }
          id { count }
        }
      }
    }
  }
  
  # ============================================
  # RELIABILITY METRICS: 60-90 DAYS (Baseline)
  # ============================================
  
  # Operating Time: 60-90 days (excludes fault states)
  operatingTime60to90d: workcenterHistory(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { occurAt: { _gte: $window90dStart } }
        { occurAt: { _lt: $window60dStart } }
        { mode: { countAsProductionTime: { _eq: true } } }
        { state: { isFault: { _eq: false } } }
      ]
    }
  ) {
    edges {
      node {
        workcenterId
        _aggregate {
          runTime { sum }
        }
      }
    }
  }
  
  # Faults: 60-90 days (runTime = repair time)
  faults60to90d: workcenterHistory(
    where: {
      _and: [
        { workcenterId: { _eq: $wcId } }
        { occurAt: { _gte: $window90dStart } }
        { occurAt: { _lt: $window60dStart } }
        { state: { isFault: { _eq: true } } }
      ]
    }
  ) {
    edges {
      node {

       workcenterId
        _aggregate {
          runTime { sum }
          id { count }
        }
      }
    }
  }
}

